package com.app.controller;import com.app.dto.FestivalOtherCollectionDtos.*;import com.app.security.UserPrincipal;import com.app.service.FestivalOtherCollectionService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/society/festivals/{festivalId}/other-collections") @RequiredArgsConstructor public class FestivalOtherCollectionController {private final FestivalOtherCollectionService service;@GetMapping public List<Dto> list(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long festivalId){return service.list(p.getAccountId(),festivalId);}@PostMapping public ResponseEntity<Dto> create(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long festivalId,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(p.getAccountId(),p.getUserId(),festivalId,r));}@PutMapping("/{id}") public Dto update(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long festivalId,@PathVariable Long id,@Valid @RequestBody Request r){return service.update(p.getAccountId(),p.getUserId(),id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long festivalId,@PathVariable Long id){service.delete(p.getAccountId(),p.getUserId(),id);}}
